solution.code:
type Status = 'active' | 'archived' | 'pending';

function setStatus(s: Status) {
  console.log('set', s);
}

function badge(s: Status): string {
  return s === 'active' ? 'green' : 'gray';
}

setStatus('active');
console.log(badge('archived'));

type Result<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };

function parseAge(input: string): Result<number> {
  const n = Number(input);
  if (Number.isNaN(n)) return { ok: false, error: 'not a number' };
  return { ok: true, data: n };
}

const r = parseAge('42');
if (r.ok) console.log(r.data); else console.log(r.error);
